+    assert(strstr(s_usart1_tx_capture, "dir=RELAY_TX") == NULL);
+    s_mock_tick_ms = 3250U;
+    minimc_proto_poll();
+    drain_all_usart1();
+    assert(strstr(s_usart1_tx_capture, "status=TIMEOUT") == NULL);
+    /* Recovery B2: Restore forward_uart_send_raw, verify next TH relay + ACK succeeds */
+    s_forward_send_ok = true;
+    clear_usart1_capture();
+    send_test_frame(MINIMC_NODE_TH, MINIMC_CMD_GET_VERSION, NULL, 0U);
